RERULES = {'web/src/views/MetricsView.tsx': [('<Coins className="h-3\\.5 w-3\\.5" />\\s*Total Spent', '<Coins className="h-3.5 w-3.5" /> {tx(\'metrics.totalSpent\')}'), ('<Wallet className="h-3\\.5 w-3\\.5" />\\s*Wallet Balance \\(live\\)', '<Wallet className="h-3.5 w-3.5" /> {tx(\'metrics.walletBalance\')}'), ('<PieChart className="h-4 w-4 text-primary" />\\s*Token Composition', '<PieChart className="h-4 w-4 text-primary" /> {tx(\'metrics.tokenComposition\')}'), ('<BarChart3 className="h-4 w-4 text-primary" />\\s*Cost by Model', '<BarChart3 className="h-4 w-4 text-primary" /> {tx(\'metrics.costByModel\')}'), ('<Layers className="h-4 w-4 text-primary" />\\s*Top Books by Cost', '<Layers className="h-4 w-4 text-primary" /> {tx(\'metrics.topBooks\')}'), ('<BookOpen className="h-4 w-4 text-primary" />\\s*Books', '<BookOpen className="h-4 w-4 text-primary" /> {tx(\'metrics.booksTitle\')}'), ('<Wallet className="h-4 w-4 text-primary" />\\s*Provider Credit \\(raw\\)', '<Wallet className="h-4 w-4 text-primary" /> {tx(\'metrics.providerCredit\')}'), ('>\\s*No data yet\\.\\s*<', ">{tx('metrics.noData')}</")], 'web/src/views/BookDetailView.tsx': [('(?m)^\\s*Retry\\s*$', "{t('common.retry')}"), ('(?m)^\\s*Read\\s*$', "{t('book.read')}"), ('(?m)^\\s*Done\\s*$', "{t('book.done')}"), ('(?m)^\\s*\\+ Add Row\\s*$', "{t('book.addRow')}"), ('(?m)^\\s*Merge Duplicates\\s*$', "{t('book.mergeDuplicates')}"), ('(?m)^\\s*Download ZIP\\s*$', "{t('book.downloadZip')}")], 'web/src/views/ToolsView.tsx': [('(?m)^\\s*Download DOCX\\s*$', "{t('tools.downloadDocx')}"), ('(?m)^\\s*Download PDF\\s*$', "{t('tools.downloadPdf')}")], 'web/src/components/ui/ChapterSelector.tsx': [('(?m)^\\s*All\\s*$', "{t('chaptersel.all')}"), ('(?m)^\\s*First 3\\s*$', "{t('chaptersel.first3')}"), ('(?m)^\\s*First 5\\s*$', "{t('chaptersel.first5')}"), ('(?m)^\\s*Clear\\s*$', "{t('chaptersel.clear')}")]}


MIN_MATCH = 0.5  # if fewer than 50% of a file's rules match -> skip file (version mismatch)


def sep(rel):
    return rel.replace('/', os.sep)


def backup(path, rel, backup_dir):
    dst = os.path.join(backup_dir, sep(rel))
    os.makedirs(os.path.dirname(dst), exist_ok=True)
    shutil.copy2(path, dst)


def main():
    if not os.path.isdir(WEB):
        print('[ERR] web/src not found. Run this from the repo root, e.g. E:\\SITE\\tran')
        sys.exit(1)

    APPLY_MODE = '--apply' in sys.argv
    stamp = time.strftime('%Y%m%d_%H%M%S')
    backup_dir = os.path.join(ROOT, '.tome_backup_' + stamp)
    print('== Tome i18n phase 8 ==  mode: %s' % ('APPLY' if APPLY_MODE else 'DRY-RUN'))
    print('   repo: %s' % ROOT)
    print()

    skipped_files = []

    # ---------------- Phase 1: full-file replacements ----------------
    print('--- Phase 1: rewritten files (i18n core + 3 views) ---')
    for rel, b64 in PAYLOADS.items():
        path = os.path.join(ROOT, sep(rel))
        if not os.path.exists(path):
            print('  [MISS] %s  (not found)' % rel)
            skipped_files.append(rel)
            continue
        new = gzip.decompress(base64.b64decode(b64))
        old = open(path, 'rb').read()
        if old == new:
            print('  [ OK ] %s  (already up to date)' % rel)
            continue
        print('  [WRT ] %s  (%d -> %d bytes)' % (rel, len(old), len(new)))
        if APPLY_MODE:
            backup(path, rel, backup_dir)
            open(path, 'wb').write(new)
    print()

    # ---------------- Phase 2: exact-match replacement tables ----------------
    print('--- Phase 2: replacement tables (remaining views/components) ---')
    paths = list(dict.fromkeys(list(RULES.keys()) + list(RERULES.keys())))
    for rel in paths:
        path = os.path.join(ROOT, sep(rel))
        if not os.path.exists(path):
            print('  [MISS] %s  (not found)' % rel)
            skipped_files.append(rel)
            continue
        text = open(path, encoding='utf-8').read()
        rules = RULES.get(rel, [])
        rrules = RERULES.get(rel, [])
        total = len(rules) + len(rrules)
        matched, missed = 0, []
        for old, new in rules:
            n = text.count(old)
            if n == 0:
                missed.append('exact: ' + old.strip()[:70])
            else:
                text = text.replace(old, new)
                matched += 1
        for pat, repl in rrules:
            text, n = re.subn(pat, repl, text)
            if n == 0:
                missed.append('regex: ' + pat[:70])
            else:
                matched += 1
        rate = matched / total if total else 1.0
        if total and rate < MIN_MATCH:
            print('  [SKIP] %s  only %d/%d rules matched - wrong version or already patched'
                  % (rel, matched, total))
            skipped_files.append(rel)
            continue
        status = 'OK ' if not missed else 'WARN'
        print('  [%s] %s  %d/%d rules matched%s'
              % (status, rel, matched, total, '' if not missed else '  (%d missed)' % len(missed)))
        for m in missed:
            print('        missed -> ' + m)
        if APPLY_MODE:
            backup(path, rel, backup_dir)
            open(path, 'w', encoding='utf-8', newline='').write(text)
    print()

    # ---------------- Leftover scan ----------------
    if APPLY_MODE:
        print('--- Leftover English scan (patched files) ---')
        pat_jsx = re.compile(r">([A-Z][A-Za-z0-9'’&/\-.,() ]{5,80})<")
        pat_str = re.compile(r"'(Failed to [^']{4,60}|Please [^']{4,80})'")
        leftovers = []
        for rel in list(PAYLOADS.keys()) + paths:
            if rel == 'web/src/lib/i18n.tsx':
                continue  # English source strings live in the dictionary by design
            path = os.path.join(ROOT, sep(rel))
            if not os.path.exists(path):
                continue
            for i, line in enumerate(open(path, encoding='utf-8', errors='ignore'), 1):
                for m in pat_jsx.findall(line):
                    leftovers.append('%s:%d  JSX >%s<' % (rel, i, m.strip()))
                for m in pat_str.findall(line):
                    leftovers.append('%s:%d  string %r' % (rel, i, m))
        if leftovers:
            print('  %d possible leftovers (review these):' % len(leftovers))
            for l in leftovers[:40]:
                print('   - ' + l)
        else:
            print('  no obvious hardcoded English strings found.')

    print()
    if skipped_files:
        print('WARNING: %d file(s) skipped -> %s' % (len(skipped_files), ', '.join(skipped_files)))
        print('If a file was skipped, its source differs from upstream. Paste the dry-run')
        print('output and I will adjust the rules for your exact version.')
        sys.exit(2)
    print('Next step:  cd web && npm run build')


if __name__ == '__main__':
    main()